import { useCallback, useEffect, useMemo, useRef, useState, type FormEvent, type ReactNode } from 'react';
import { api, ApiError } from './api';
import type { AnalyzerRun, Finding, PathOverride, Report, Scan, Severity, SourcePreview, Tool, TreeNode, Workspace } from './types';

type Route = { page: 'home' | 'workspaces' | 'workspace' | 'files' | 'history' | 'scan' | 'tools' | 'settings' | 'about'; id?: string };
type Notice = { kind: 'error' | 'info'; text: string } | null;
type ScanEvent = { type: string; stage?: string; status?: string; message?: string; analyzer_id?: string; name?: string; findings?: number; error?: string; state?: string; at: number };

function parseRoute(pathname = window.location.pathname): Route {
  const segments = pathname.split('/').filter(Boolean);
  if (!segments.length) return { page: 'home' };
  if (segments[0] === 'workspaces' && segments[2] === 'files') return { page: 'files', id: segments[1] };
  if (segments[0] === 'workspaces' && segments[2] === 'scans') return { page: 'history', id: segments[1] };
  if (segments[0] === 'workspaces' && segments[1]) return { page: 'workspace', id: segments[1] };
  if (segments[0] === 'workspaces') return { page: 'workspaces' };
  if (segments[0] === 'scans' && segments[1]) return { page: 'scan', id: segments[1] };
  if (segments[0] === 'tools' || segments[0] === 'settings' || segments[0] === 'about') return { page: segments[0] };
  return { page: 'home' };
}

function href(route: Route) {
  if (route.page === 'home') return '/';
  if (route.page === 'workspaces') return '/workspaces';
  if (route.page === 'workspace') return `/workspaces/${route.id}`;
  if (route.page === 'files') return `/workspaces/${route.id}/files`;
  if (route.page === 'history') return `/workspaces/${route.id}/scans`;
  if (route.page === 'scan') return `/scans/${route.id}`;
  return `/${route.page}`;
}

function date(value?: string | null) { return value ? new Intl.DateTimeFormat(undefined, { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value)) : 'Not analyzed yet'; }
function duration(ms?: number) { return ms === undefined ? '—' : ms < 1000 ? `${ms}ms` : `${(ms / 1000).toFixed(1)}s`; }

export function App() {
  const [route, setRoute] = useState(parseRoute);
  const [notice, setNotice] = useState<Notice>(null);
  const [addOpen, setAddOpen] = useState(false);
  const [closeOpen, setCloseOpen] = useState(false);
  const [closing, setClosing] = useState(false);
  const go = useCallback((next: Route) => { window.history.pushState({}, '', href(next)); setRoute(next); }, []);
  const closeApp = async () => { setClosing(true); try { await api.stopServer(); setCloseOpen(false); setNotice({ kind: 'info', text: 'Blunt Code is closing. You can close this tab.' }); } catch (error) { setNotice({ kind: 'error', text: message(error) }); setClosing(false); } };
  useEffect(() => { const handler = () => setRoute(parseRoute()); window.addEventListener('popstate', handler); return () => window.removeEventListener('popstate', handler); }, []);
  return <div className="app-frame">
    <AppShell route={route} onNavigate={go} onAdd={() => setAddOpen(true)} onClose={() => setCloseOpen(true)} />
    <main className="main" id="main-content">
      {notice && <NoticeBox notice={notice} onDismiss={() => setNotice(null)} />}
      <Page route={route} go={go} notify={setNotice} onAdd={() => setAddOpen(true)} />
    </main>
    {addOpen && <AddWorkspaceDialog onClose={() => setAddOpen(false)} onCreated={(workspace) => { setAddOpen(false); go({ page: 'workspace', id: workspace.id }); }} notify={setNotice} />}
    {closeOpen && <ConfirmationDialog title="Close Blunt Code?" description="This ends the local app. Any active scan will be cancelled; your workspaces and reports stay saved on this computer." confirmLabel="Close app" busy={closing} onCancel={() => setCloseOpen(false)} onConfirm={() => void closeApp()} />}
    <AppFooter />
  </div>;
}

function AppShell({ route, onNavigate, onAdd, onClose }: { route: Route; onNavigate: (route: Route) => void; onAdd: () => void; onClose: () => void }) {
  const items: Array<[Route, string]> = [[{ page: 'home' }, 'Home'], [{ page: 'workspaces' }, 'Workspaces'], [{ page: 'tools' }, 'Tools'], [{ page: 'settings' }, 'Settings']];
  return <header className="app-nav">
    <a className="brand" href="/" onClick={(event) => { event.preventDefault(); onNavigate({ page: 'home' }); }}><span aria-hidden="true">BC</span><b>Blunt Code</b></a>
    <nav aria-label="Main navigation">{items.map(([next, label]) => <a key={label} href={href(next)} className={route.page === next.page ? 'active' : ''} onClick={(event) => { event.preventDefault(); onNavigate(next); }}>{label}</a>)}</nav>
    <div className="nav-actions"><button className="button secondary close-app" onClick={onClose}>Close app</button><button className="button primary add" onClick={onAdd}>Add workspace</button></div>
  </header>;
}
function AppFooter() { return <footer className="app-footer"><span>Blunt Code · local code analysis for Windows</span><span>No account. No telemetry.</span></footer>; }

function Page({ route, go, notify, onAdd }: { route: Route; go: (r: Route) => void; notify: (n: Notice) => void; onAdd: () => void }) {
  switch (route.page) {
    case 'home': return <Home go={go} onAdd={onAdd} notify={notify} />;
    case 'workspaces': return <Workspaces go={go} onAdd={onAdd} notify={notify} />;
    case 'workspace': return <WorkspacePage id={route.id!} go={go} notify={notify} />;
    case 'files': return <FilesPage id={route.id!} notify={notify} />;
    case 'history': return <HistoryPage workspaceId={route.id!} go={go} />;
    case 'scan': return <ScanPage id={route.id!} go={go} notify={notify} />;
    case 'tools': return <ToolsPage notify={notify} />;
    case 'settings': return <SettingsPage notify={notify} />;
    case 'about': return <AboutPage />;
  }
}

function useLoad<T>(load: () => Promise<T>, deps: unknown[]) {
  const [data, setData] = useState<T>(); const [error, setError] = useState<string>(); const [loading, setLoading] = useState(true);
  const reload = useCallback(async () => { setLoading(true); setError(undefined); try { setData(await load()); } catch (e) { setError(message(e)); } finally { setLoading(false); } }, deps); // eslint-disable-line react-hooks/exhaustive-deps
  useEffect(() => { void reload(); }, [reload]);
  return { data, error, loading, reload };
}
function message(error: unknown) { return error instanceof ApiError ? `${error.code}: ${error.message}` : error instanceof Error ? error.message : 'An unexpected error occurred.'; }
function NoticeBox({ notice, onDismiss }: { notice: Exclude<Notice, null>; onDismiss: () => void }) { return <div className={`notice ${notice.kind}`} role={notice.kind === 'error' ? 'alert' : 'status'}>{notice.text}<button onClick={onDismiss} aria-label="Dismiss">×</button></div>; }
function ErrorPanel({ error, retry }: { error: string; retry?: () => void }) { return <section className="error-panel" role="alert"><h2>Could not load this view</h2><p>{error}</p>{retry && <button className="button secondary" onClick={retry}>Try again</button>}</section>; }
function Loading() { return <div className="loading" aria-live="polite">Loading…</div>; }
function Empty({ title, children, action }: { title: string; children: ReactNode; action?: ReactNode }) { return <section className="empty"><h2>{title}</h2><p>{children}</p>{action}</section>; }

function Home({ go, onAdd, notify }: { go: (r: Route) => void; onAdd: () => void; notify: (n: Notice) => void }) {
  const workspaces = useLoad(api.workspaces, []); const tools = useLoad(api.tools, []);
  const readyTools = tools.data?.filter((tool) => tool.ready).length ?? 0;
  return <div className="page dashboard-page"><header className="dashboard-heading"><div><h1>Workspaces</h1><p>Run a local scan, then follow every result in one place.</p></div></header>
    <section className="dashboard-list" aria-labelledby="recent-workspaces"><header><div><h2 id="recent-workspaces">Recent projects</h2><p>{workspaces.data?.length ? `${workspaces.data.length} saved locally` : 'Choose a project to begin.'}</p></div><button className="text-button" onClick={() => go({ page: 'workspaces' })}>All workspaces</button></header>
      {workspaces.loading ? <Loading /> : workspaces.error ? <ErrorPanel error={workspaces.error} retry={workspaces.reload} /> : !workspaces.data?.length ? <Empty title="No workspaces yet" action={<button className="button primary" onClick={onAdd}>Add workspace</button>}>Choose a folder. Blunt Code never changes your source files.</Empty> : <WorkspaceTable workspaces={workspaces.data.slice(0, 6)} go={go} notify={notify} onRemoved={workspaces.reload} />}
    </section>
    <section className="dashboard-tools" aria-label="Tool readiness">{tools.loading ? <Loading /> : tools.error ? <ErrorPanel error={tools.error} retry={tools.reload} /> : <><div><span>Tool status</span><strong>{readyTools} of {tools.data?.length ?? 0} tools ready</strong><p>Managed locally. No source files leave this computer.</p></div><button className="button secondary" onClick={() => go({ page: 'tools' })}>Manage tools</button></>}</section>
  </div>;
}

function PrivacyNotice() { return <aside className="privacy"><strong>Private by design</strong><span>Your source code stays on this computer. No account or telemetry required.</span></aside>; }

function Workspaces({ go, onAdd, notify }: { go: (r: Route) => void; onAdd: () => void; notify: (n: Notice) => void }) { const state = useLoad(api.workspaces, []); return <div className="page"><header className="page-heading"><div><p className="eyebrow">Workspaces</p><h1>Your local projects</h1><p>Each workspace saves its file rules and scan history on this computer.</p></div><button className="button primary" onClick={onAdd}>+ Add workspace</button></header>{state.loading ? <Loading /> : state.error ? <ErrorPanel error={state.error} retry={state.reload} /> : state.data?.length ? <div className="workspace-grid">{state.data.map((workspace) => <WorkspaceCard key={workspace.id} workspace={workspace} go={go} notify={notify} onRemoved={state.reload} />)}</div> : <Empty title="No workspaces yet">Use the folder picker to add a project.</Empty>}</div>; }

function WorkspaceTable({ workspaces, go, notify, onRemoved }: { workspaces: Workspace[]; go: (r: Route) => void; notify: (n: Notice) => void; onRemoved: () => void }) { return <div className="workspace-table table-wrap"><table><thead><tr><th>Project</th><th>Languages</th><th>Last scan</th><th>Status</th><th><span className="sr-only">Actions</span></th></tr></thead><tbody>{workspaces.map((workspace) => <WorkspaceTableRow key={workspace.id} workspace={workspace} go={go} notify={notify} onRemoved={onRemoved} />)}</tbody></table></div>; }
function WorkspaceTableRow({ workspace, go, notify, onRemoved }: { workspace: Workspace; go: (r: Route) => void; notify: (n: Notice) => void; onRemoved: () => void }) { const scan = workspace.latest_scan; const [deleteOpen, setDeleteOpen] = useState(false); const [deleting, setDeleting] = useState(false); async function analyze() { try { const active = await api.startScan(workspace.id); go({ page: 'scan', id: active.id }); } catch (e) { notify({ kind: 'error', text: message(e) }); } } async function remove() { setDeleting(true); try { await api.deleteWorkspace(workspace.id); setDeleteOpen(false); notify({ kind: 'info', text: 'Workspace removed from Blunt Code.' }); onRemoved(); } catch (e) { notify({ kind: 'error', text: message(e) }); setDeleting(false); } } return <><tr><td className="workspace-project"><strong>{workspace.name}</strong><code title={workspace.root_path}>{workspace.root_path}</code></td><td className="workspace-languages"><LanguageBadges languages={workspace.languages} /></td><td className="workspace-last-scan">{scan ? <><span>{scan.finished_at ? date(scan.finished_at) : 'In progress'}</span><small>{scan.total_findings ?? 0} {(scan.total_findings ?? 0) === 1 ? 'finding' : 'findings'}</small></> : <span>No scans yet</span>}</td><td><span className={`state ${scan?.state ?? 'ready'}`}>{scan ? scan.state.replaceAll('_', ' ') : 'Ready'}</span></td><td><div className="workspace-actions"><button className="text-button" onClick={() => go({ page: 'workspace', id: workspace.id })}>Details</button><button className="button primary" onClick={() => void analyze()}>Run scan</button><button className="text-button danger-text" onClick={() => setDeleteOpen(true)} aria-label={`Remove ${workspace.name}`}>Remove</button></div></td></tr>{deleteOpen && <tr><td colSpan={5}><ConfirmationDialog title="Remove this workspace?" description="This removes the saved workspace, file rules, and local scan history from Blunt Code. Your project files will not be changed." confirmLabel="Remove workspace" busy={deleting} onCancel={() => setDeleteOpen(false)} onConfirm={remove} /></td></tr>}</>; }

function WorkspaceCard({ workspace, go, notify, onRemoved }: { workspace: Workspace; go: (r: Route) => void; notify?: (n: Notice) => void; onRemoved?: () => void }) {
  const scan = workspace.latest_scan;
  const [deleteOpen, setDeleteOpen] = useState(false); const [deleting, setDeleting] = useState(false);
  async function analyze(event: React.MouseEvent) { event.stopPropagation(); try { const active = await api.startScan(workspace.id); go({ page: 'scan', id: active.id }); } catch (e) { notify?.({ kind: 'error', text: message(e) }); } }
  async function remove() { setDeleting(true); try { await api.deleteWorkspace(workspace.id); setDeleteOpen(false); notify?.({ kind: 'info', text: 'Workspace removed from Blunt Code.' }); onRemoved?.(); } catch (e) { notify?.({ kind: 'error', text: message(e) }); setDeleting(false); } }
  const findings = scan?.total_findings ?? 0;
  return <><article className="workspace-card"><header className="workspace-identity"><h3>{workspace.name}</h3><code title={workspace.root_path}>{workspace.root_path}</code></header><section className="workspace-languages"><span>Languages</span><LanguageBadges languages={workspace.languages} /></section><section className="workspace-analysis"><div><span>Latest analysis</span>{scan && <span className={`state ${scan.state}`}>{scan.state.replaceAll('_', ' ')}</span>}</div>{scan ? <><strong>{findings} {findings === 1 ? 'finding' : 'findings'}</strong><p>{scan.finished_at ? `Completed ${date(scan.finished_at)}` : 'Analysis in progress'}</p></> : <p>No analysis yet. Run a scan to create the first report.</p>}</section><footer><button className="text-button" onClick={() => go({ page: 'workspace', id: workspace.id })}>Open details</button><button className="button primary" onClick={analyze}>Run scan</button><button className="text-button danger-text" onClick={() => setDeleteOpen(true)} aria-label={`Remove ${workspace.name}`}>Remove</button></footer></article>{deleteOpen && <ConfirmationDialog title="Remove this workspace?" description="This removes the saved workspace, file rules, and local scan history from Blunt Code. Your project files will not be changed." confirmLabel="Remove workspace" busy={deleting} onCancel={() => setDeleteOpen(false)} onConfirm={remove} />}</>;
}
function LanguageBadges({ languages }: { languages?: string[] }) { return languages?.length ? <div className="badges" aria-label="Detected languages">{languages.map((language) => <span className="badge" key={language}>{languageNames[language] ?? language}</span>)}</div> : <span className="muted">No supported source languages found</span>; }
const languageNames: Record<string, string> = { javascript: 'JavaScript', python: 'Python', typescript: 'TypeScript' };
function SeverityCounts({ scan }: { scan?: Scan }) { const values: Array<[Severity, number | undefined]> = [['critical', scan?.critical_count], ['high', scan?.high_count], ['medium', scan?.medium_count], ['low', scan?.low_count]]; return <div className="severity-counts">{values.map(([severity, count]) => <span key={severity} className={severity}>{count ?? 0} <small>{severity}</small></span>)}</div>; }
function ToolSummary({ tools }: { tools: Tool[] }) { return <div className="tool-summary">{tools.length ? tools.map((tool) => <span key={tool.id}><i className={`dot ${tool.ready ? 'ready' : 'not-ready'}`} />{tool.id}: {tool.ready ? 'ready' : 'not installed'}</span>) : <span className="muted">Tool status will appear once the backend is ready.</span>}</div>; }

function WorkspacePage({ id, go, notify }: { id: string; go: (r: Route) => void; notify: (n: Notice) => void }) {
  const workspace = useLoad(() => api.workspace(id), [id]); const scans = useLoad(() => api.scans(id), [id]); const [deleteOpen, setDeleteOpen] = useState(false); const [deleting, setDeleting] = useState(false);
  const latest = workspace.data?.latest_scan ?? scans.data?.[0];
  async function start() { try { const scan = await api.startScan(id); go({ page: 'scan', id: scan.id }); } catch (e) { notify({ kind: 'error', text: message(e) }); } }
  async function remove() { setDeleting(true); try { await api.deleteWorkspace(id); go({ page: 'workspaces' }); notify({ kind: 'info', text: 'Workspace removed from Blunt Code.' }); } catch (e) { notify({ kind: 'error', text: message(e) }); setDeleting(false); } }
  if (workspace.loading) return <div className="page"><Loading /></div>;
  if (workspace.error) return <div className="page"><ErrorPanel error={workspace.error} retry={workspace.reload} /></div>;
  const item = workspace.data!;
  return <div className="page"><header className="page-heading workspace-heading"><div><p className="eyebrow">Workspace</p><h1>{item.name}</h1><code>{item.root_path}</code><LanguageBadges languages={item.languages} /></div><div className="workspace-next"><span>Next step</span><strong>Run a fresh analysis</strong><button className="button primary" onClick={start}>Run scan</button></div></header>
    <div className="action-row"><button className="button secondary" onClick={() => go({ page: 'files', id })}>Configure files</button><button className="button secondary" disabled={!latest} onClick={() => latest && go({ page: 'scan', id: latest.id })}>View last report</button>{latest && <a className="button secondary" href={api.markdownUrl(latest.id)}>Export Markdown</a>}<button className="button secondary" onClick={() => notify({ kind: 'info', text: 'Workspace settings are managed through file rules in this V1.' })}>Workspace settings</button><button className="button danger" onClick={() => setDeleteOpen(true)}>Remove workspace</button></div>
    <section className="summary-grid" aria-label="Latest scan summary"><SummaryCard label="Critical + high" value={(latest?.critical_count ?? 0) + (latest?.high_count ?? 0)} tone="high" /><SummaryCard label="Medium" value={latest?.medium_count ?? 0} tone="medium" /><SummaryCard label="Low + info" value={(latest?.low_count ?? 0) + (latest?.info_count ?? 0)} /><SummaryCard label="Total findings" value={latest?.total_findings ?? 0} /><SummaryCard label="New since last scan" value={latest?.new_count ?? 0} /><SummaryCard label="Fixed since last scan" value={latest?.fixed_count ?? 0} /></section>
    <section className="split-section"><div><h2>Latest analysis</h2>{latest ? <><p className="muted">{latest.state.replaceAll('_', ' ')} · {date(latest.finished_at ?? latest.started_at)}</p>{latest.error_summary && <div className="inline-warning">Warning: {latest.error_summary}</div>}<AnalyzerStatuses runs={latest.analyzer_runs} /></> : <Empty title="Ready when you are">Run the first scan to get a combined report.</Empty>}</div><div><h2>Scan history</h2>{scans.loading ? <Loading /> : scans.error ? <ErrorPanel error={scans.error} retry={scans.reload} /> : <HistoryTable scans={scans.data ?? []} go={go} />}</div></section>
  {deleteOpen && <ConfirmationDialog title="Remove this workspace?" description="This removes the saved workspace, file rules, and local scan history from Blunt Code. Your project files will not be changed." confirmLabel="Remove workspace" busy={deleting} onCancel={() => setDeleteOpen(false)} onConfirm={remove} />}</div>;
}
function SummaryCard({ label, value, tone }: { label: string; value: number; tone?: string }) { return <article className={`summary-card ${tone ?? ''}`}><strong>{value}</strong><span>{label}</span></article>; }
function AnalyzerStatuses({ runs }: { runs?: AnalyzerRun[] }) { return <div className="analyzers"><h3>Analyzer status</h3>{runs?.length ? runs.map((run) => <div className="analyzer-row" key={run.analyzer_id}><span>{run.analyzer_id}</span><span className={`state ${run.status}`}>{run.status}</span>{run.message && <small>{run.message}</small>}</div>) : <p className="muted">Analyzer detail appears after a scan.</p>}</div>; }

function FilesPage({ id, notify }: { id: string; notify: (n: Notice) => void }) {
  const workspace = useLoad(() => api.workspace(id), [id]); const [query, setQuery] = useState(''); const [nodes, setNodes] = useState<TreeNode[]>([]); const [treeError, setTreeError] = useState<string>(); const [loadingTree, setLoadingTree] = useState(true); const [rules, setRules] = useState<{ rules: Array<{ rule_type: 'include' | 'exclude'; pattern: string; enabled?: boolean }> }>({ rules: [] }); const [overrides, setOverrides] = useState<PathOverride[]>([]); const [treeKey, setTreeKey] = useState(0);
  const loadTree = useCallback(async () => { setLoadingTree(true); try { setNodes(await api.tree(id)); setTreeError(undefined); } catch (e) { setTreeError(message(e)); } finally { setLoadingTree(false); } }, [id]);
  useEffect(() => { void loadTree(); void Promise.all([api.rules(id), api.pathOverrides(id)]).then(([savedRules, savedOverrides]) => { setRules(savedRules as typeof rules); setOverrides(savedOverrides); }).catch((e) => notify({ kind: 'error', text: message(e) })); }, [id, loadTree]);
  const save = async () => { try { await api.saveRules(id, rules); await api.savePathOverrides(id, overrides); await loadTree(); setTreeKey((value) => value + 1); notify({ kind: 'info', text: 'File selection saved for this workspace.' }); } catch (e) { notify({ kind: 'error', text: message(e) }); } };
  const filtered = query ? nodes.filter((node) => node.path.toLowerCase().includes(query.toLowerCase())) : nodes;
  return <div className="page"><header className="page-heading"><div><p className="eyebrow">File selection</p><h1>{workspace.data?.name ?? 'Workspace files'}</h1><p>Choose source paths to analyze. Default exclusions protect dependencies and build output.</p></div><div className="action-row"><button className="button secondary" onClick={() => { setRules({ rules: [] }); setOverrides([]); }}>Reset to defaults</button><button className="button primary" onClick={save}>Save selection</button></div></header>
    <section className="file-layout"><div className="tree-panel"><label className="search"><span>Search paths</span><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="src or package.json" /></label>{loadingTree ? <Loading /> : treeError ? <ErrorPanel error={treeError} retry={loadTree} /> : filtered.length ? <FileTree key={treeKey} nodes={filtered} workspaceId={id} overrides={overrides} onOverrides={setOverrides} /> : <Empty title="No matching paths">Try a shorter search.</Empty>}</div><RuleEditor rules={rules.rules} setRules={(items) => setRules({ rules: items })} /></section>
  </div>;
}
function FileTree({ nodes, workspaceId, overrides, onOverrides }: { nodes: TreeNode[]; workspaceId: string; overrides: PathOverride[]; onOverrides: (items: PathOverride[]) => void }) {
  const [expanded, setExpanded] = useState<Set<string>>(new Set()); const [children, setChildren] = useState<Record<string, TreeNode[]>>({});
  async function expand(node: TreeNode) { if (node.type !== 'directory') return; const next = new Set(expanded); if (next.has(node.path)) { next.delete(node.path); setExpanded(next); return; } next.add(node.path); setExpanded(next); if (!children[node.path]) { try { const loaded = await api.tree(workspaceId, node.path); setChildren((old) => ({ ...old, [node.path]: loaded })); } catch { /* Root remains usable; API errors are surfaced on subsequent retry. */ } } }
  function included(node: TreeNode) { const matching = overrides.filter((item) => node.path === item.relative_path || node.path.startsWith(`${item.relative_path}/`)).sort((a, b) => b.relative_path.length - a.relative_path.length)[0]; return matching ? matching.mode === 'include' : node.included ?? !node.excluded_reason; }
  function toggle(node: TreeNode) { const next = !included(node); onOverrides([...overrides.filter((item) => item.relative_path !== node.path), { relative_path: node.path, mode: next ? 'include' : 'exclude' }]); }
  return <ul className="file-tree" aria-label="Workspace file tree">{nodes.map((node) => <li key={node.path}><div className="tree-row"><button className="tree-toggle" aria-label={expanded.has(node.path) ? `Collapse ${node.name}` : `Expand ${node.name}`} disabled={node.type !== 'directory'} onClick={() => void expand(node)}>{node.type === 'directory' ? (expanded.has(node.path) ? '−' : '+') : '·'}</button><input type="checkbox" checked={included(node)} ref={(input) => { if (input) input.indeterminate = Boolean(node.partial && !overrides.some((item) => node.path === item.relative_path)); }} onChange={() => toggle(node)} aria-label={`Include ${node.path}`} /><span className="tree-name">{node.name}</span>{node.excluded_reason && <small>Excluded: {node.excluded_reason}</small>}</div>{expanded.has(node.path) && <div className="tree-children"><FileTree nodes={children[node.path] ?? []} workspaceId={workspaceId} overrides={overrides} onOverrides={onOverrides} /></div>}</li>)}</ul>;
}
function RuleEditor({ rules, setRules }: { rules: Array<{ rule_type: 'include' | 'exclude'; pattern: string; enabled?: boolean }>; setRules: (next: Array<{ rule_type: 'include' | 'exclude'; pattern: string; enabled?: boolean }>) => void }) {
  function edit(index: number, patch: Partial<(typeof rules)[number]>) { setRules(rules.map((rule, i) => i === index ? { ...rule, ...patch } : rule)); }
  return <aside className="rule-editor"><h2>Rules</h2><p className="muted">Rules apply to new files too.</p>{rules.map((rule, index) => <div className="rule" key={`${rule.pattern}-${index}`}><select value={rule.rule_type} onChange={(event) => edit(index, { rule_type: event.target.value as 'include' | 'exclude' })}><option value="include">Include</option><option value="exclude">Exclude</option></select><input value={rule.pattern} onChange={(event) => edit(index, { pattern: event.target.value })} aria-label="Rule pattern" /><button className="icon-button" onClick={() => setRules(rules.filter((_, i) => i !== index))} aria-label="Remove rule">×</button></div>)}<button className="text-button" onClick={() => setRules([...rules, { rule_type: 'exclude', pattern: '' }])}>+ Add rule</button></aside>;
}

function HistoryPage({ workspaceId, go }: { workspaceId: string; go: (r: Route) => void }) { const state = useLoad(() => api.scans(workspaceId), [workspaceId]); return <div className="page"><header className="page-heading"><div><p className="eyebrow">Scan history</p><h1>Previous analyses</h1><p>Reports and findings are stored only on this computer.</p></div></header>{state.loading ? <Loading /> : state.error ? <ErrorPanel error={state.error} retry={state.reload} /> : <HistoryTable scans={state.data ?? []} go={go} />}</div>; }
const historyPageSize = 6;
function HistoryTable({ scans, go }: { scans: Scan[]; go: (r: Route) => void }) {
  const [page, setPage] = useState(0);
  const pageCount = Math.max(1, Math.ceil(scans.length / historyPageSize));
  const currentPage = Math.min(page, pageCount - 1);
  const first = currentPage * historyPageSize;
  const visibleScans = scans.slice(first, first + historyPageSize);

  useEffect(() => { setPage(0); }, [scans]);

  if (!scans.length) return <Empty title="No scans yet">Analyze this workspace to create the first report.</Empty>;

  return <><div className="table-wrap"><table><thead><tr><th>Date</th><th>Status</th><th>Critical</th><th>High</th><th>Medium</th><th>Low</th><th>New</th><th>Fixed</th><th>Duration</th><th><span className="sr-only">Actions</span></th></tr></thead><tbody>{visibleScans.map((scan) => <tr key={scan.id}><td>{date(scan.finished_at ?? scan.started_at)}</td><td><span className={`state ${scan.state}`}>{scan.state.replaceAll('_', ' ')}</span></td><td>{scan.critical_count ?? 0}</td><td>{scan.high_count ?? 0}</td><td>{scan.medium_count ?? 0}</td><td>{scan.low_count ?? 0}</td><td>{scan.new_count ?? 0}</td><td>{scan.fixed_count ?? 0}</td><td>{duration(scan.duration_ms)}</td><td><button className="text-button" onClick={() => go({ page: 'scan', id: scan.id })}>Open report</button></td></tr>)}</tbody></table></div><nav className="history-pagination" aria-label="Scan history pagination"><span>Showing {first + 1}–{Math.min(first + historyPageSize, scans.length)} of {scans.length} scans</span><div><button className="button secondary" onClick={() => setPage(currentPage - 1)} disabled={currentPage === 0}>Previous</button><output aria-live="polite">Page {currentPage + 1} of {pageCount}</output><button className="button secondary" onClick={() => setPage(currentPage + 1)} disabled={currentPage === pageCount - 1}>Next</button></div></nav></>;
}

const stageLabels: Record<string, string> = { preparing: 'Preparing workspace', discovering: 'Detecting languages', checking_tools: 'Checking analyzers', running: 'Running analyzers', normalizing: 'Normalizing findings', generating_report: 'Generating report', completed: 'Complete' };
function ScanPage({ id, go, notify }: { id: string; go: (r: Route) => void; notify: (n: Notice) => void }) {
  const scan = useLoad(() => api.scan(id), [id]); const [events, setEvents] = useState<ScanEvent[]>([]); const [streamState, setStreamState] = useState<'connecting' | 'live' | 'reconnecting'>('connecting');
  useEffect(() => {
    if (scan.data && isTerminalScanState(scan.data.state)) {
      setStreamState('live');
      return;
    }
    let source: EventSource | undefined; let retry: number | undefined;
    const receive = (event: MessageEvent) => {
      try {
        const envelope = JSON.parse(event.data) as { type?: string; data?: Record<string, unknown> };
        const data = (envelope.data ?? envelope) as Omit<ScanEvent, 'type' | 'at'>;
        const next: ScanEvent = { ...data, type: envelope.type ?? event.type, at: Date.now() };
        setEvents((old) => [...old.slice(-23), next]);
        setStreamState('live');
        if (next.type === 'scan.completed' || next.type === 'scan.cancelled') void scan.reload();
      } catch { /* Invalid optional event payloads do not interrupt the scan. */ }
    };
    const connect = () => {
      setStreamState((state) => state === 'live' ? 'reconnecting' : state);
      source = new EventSource(`/api/v1/scans/${encodeURIComponent(id)}/events`);
      ['scan.started', 'scan.stage', 'analyzer.started', 'analyzer.completed', 'analyzer.failed', 'analyzer.skipped', 'scan.warning', 'scan.completed', 'scan.cancelled'].forEach((type) => source?.addEventListener(type, receive));
      source.addEventListener('connected', () => setStreamState('live'));
      source.onerror = () => { source?.close(); setStreamState('reconnecting'); retry = window.setTimeout(() => { void scan.reload(); connect(); }, 4000); };
    };
    connect();
    return () => { source?.close(); if (retry) window.clearTimeout(retry); };
  }, [id, scan.data?.state, scan.reload]);
  const current = scan.data;
  const terminal = current && isTerminalScanState(current.state);
  async function cancel() { try { await api.cancelScan(id); await scan.reload(); } catch (e) { notify({ kind: 'error', text: message(e) }); } }
  if (scan.loading) return <div className="page"><Loading /></div>;
  if (scan.error) return <div className="page"><ErrorPanel error={scan.error} retry={scan.reload} /></div>;
  if (!current) return <div className="page"><Loading /></div>;
  const headline = terminal ? current.state.replaceAll('_', ' ') : liveHeadline(events, current.state);
  const reportedFindings = events.reduce((total, event) => total + (event.type === 'analyzer.completed' ? event.findings ?? 0 : 0), 0);
  const findingsSoFar = Math.max(current.total_findings ?? 0, reportedFindings);
  return <div className="page scan-page"><header className="scan-header"><div><p className="eyebrow">Analysis story</p><h1>{headline}</h1><p>Started {date(current.started_at)} · elapsed {elapsed(current.started_at, current.finished_at)}</p></div><div className="scan-header-actions"><span className={`stream-state ${streamState}`} aria-live="polite"><i />{terminal ? 'Saved report' : streamState === 'live' ? 'Live updates' : streamState === 'reconnecting' ? 'Reconnecting' : 'Connecting'}</span>{!terminal && <button className="button danger" onClick={cancel}>Cancel scan</button>}</div></header><section className="progress-layout"><ScanStageList scan={current} events={events} /><aside className="scan-side"><p className="eyebrow">Results so far</p><h2>{findingsSoFar} findings {terminal ? 'collected' : 'reported so far'}</h2><SeverityCounts scan={current} />{current.error_summary && <div className="inline-warning">{current.error_summary}</div>}<AnalyzerStatuses runs={current.analyzer_runs} /></aside></section>{terminal && <ReportView scanId={id} />}</div>;
}
function isTerminalScanState(state: string) { return ['completed', 'completed_with_warnings', 'failed', 'cancelled', 'interrupted'].includes(state); }
function elapsed(start?: string | null, end?: string | null) { if (!start) return '—'; const ms = (end ? new Date(end) : new Date()).getTime() - new Date(start).getTime(); return duration(Math.max(0, ms)); }
function liveHeadline(events: ScanEvent[], state: string) { const latest = events.at(-1); if (latest?.type === 'analyzer.started') return `${latest.name ?? latest.analyzer_id ?? 'Analyzer'} is checking your code`; if (latest?.type === 'analyzer.completed') return `${latest.analyzer_id ?? 'Analyzer'} finished its pass`; if (latest?.stage) return latest.stage; return stageLabels[state] ?? 'Getting your scan ready'; }
function eventCopy(event: ScanEvent) { if (event.type === 'analyzer.started') return `${event.name ?? event.analyzer_id ?? 'Analyzer'} started`; if (event.type === 'analyzer.completed') return `${event.analyzer_id ?? 'Analyzer'} finished${event.findings === undefined ? '' : ` · ${event.findings} findings`}`; if (event.type === 'analyzer.failed') return `${event.analyzer_id ?? 'Analyzer'} needs attention${event.error ? ` · ${event.error}` : ''}`; if (event.type === 'analyzer.skipped') return `${event.analyzer_id ?? 'Analyzer'} skipped${event.message ? ` · ${event.message}` : ''}`; if (event.type === 'scan.cancelled') return 'Scan cancelled'; if (event.type === 'scan.completed') return 'Report complete'; return event.stage ?? event.message ?? 'Scan update'; }
function ScanStageList({ scan, events }: { scan: Scan; events: ScanEvent[] }) { const journey = events.filter((event) => event.type !== 'scan.started'); const fallback = scan.state === 'queued' ? 'Waiting for the scan to begin.' : scan.state === 'interrupted' ? 'Scan interrupted before every analyzer finished.' : stageLabels[scan.state] ?? 'Working'; const entries = journey.length ? journey : [{ type: 'scan.stage', stage: fallback, at: Date.now() }]; const active = !isTerminalScanState(scan.state) ? entries.at(-1) : undefined; const status = active?.type === 'analyzer.started' ? `${active.name ?? active.analyzer_id ?? 'Analyzer'} is checking your code` : active ? eventCopy(active) : scan.state === 'interrupted' ? 'Scan interrupted — completed checks are still available.' : scan.state.replaceAll('_', ' '); return <section className="stage-list"><header><div><p className="eyebrow">Analysis flow</p><h2>What is happening now</h2></div><span>{entries.length} update{entries.length === 1 ? '' : 's'}</span></header><p className={`flow-now ${active ? 'active' : ''}`} role="status" aria-live="polite"><i aria-hidden="true" />{status}</p><ol className="scan-flow">{entries.map((event, index) => { const state = event.type.includes('failed') ? 'failed' : event.type.includes('completed') ? 'done' : event.type.includes('cancelled') ? 'interrupted' : index === entries.length - 1 && !isTerminalScanState(scan.state) ? 'current' : ''; return <li className={state} key={`${event.type}-${event.at}-${index}`}><i className="flow-marker" aria-hidden="true" /><div><strong>{eventCopy(event)}</strong><small>{new Intl.DateTimeFormat(undefined, { timeStyle: 'medium' }).format(event.at)}</small></div></li>; })}</ol></section>; }

type FindingFilter = { severity: string; category: string; analyzer: string; path: string; status: string; q: string };
function ReportView({ scanId }: { scanId: string }) {
  const report = useLoad(() => api.report(scanId), [scanId]); const [filters, setFilters] = useState<FindingFilter>({ severity: '', category: '', analyzer: '', path: '', status: '', q: '' }); const [filtersOpen, setFiltersOpen] = useState(false); const [offset, setOffset] = useState(0); const [limit, setLimit] = useState(25); const [previewFinding, setPreviewFinding] = useState<Finding>(); const params = useMemo(() => ({ ...filters, limit: String(limit), offset: String(offset), sort: 'severity' }), [filters, limit, offset]); const findings = useLoad(() => api.findings(scanId, params), [scanId, ...Object.values(params)]);
  const list = findings.data?.items ?? [];
  const updateFilters = (next: FindingFilter) => { setFilters(next); setOffset(0); };
  if (report.loading) return <Loading />; if (report.error) return <ErrorPanel error={report.error} retry={report.reload} />;
  const data = report.data!;
  const activeFilterCount = Object.values(filters).filter(Boolean).length;
  const clearFilters = () => updateFilters({ severity: '', category: '', analyzer: '', path: '', status: '', q: '' });
  const noFindingsTitle = filters.analyzer ? `${analyzerName(filters.analyzer)} reported no findings` : 'No findings match these filters';
  const noFindingsCopy = filters.analyzer ? 'This analyzer completed without reportable issues for the selected files.' : 'Try clearing one or more filters.';
  return <section className="report"><header className="report-header"><div><p className="eyebrow">Report</p><h2>Analysis overview</h2><p>{data.warnings?.length ? 'Analysis completed with limitations.' : 'Analysis completed.'}</p></div><a className="button secondary" href={api.markdownUrl(scanId)}>Export Markdown</a></header>{data.warnings?.length ? <div className="inline-warning"><strong>Incomplete analysis</strong>{data.warnings.map((warning) => <span key={warning}>{warning}</span>)}</div> : null}<section className="summary-grid"><SummaryCard label="Total findings" value={data.scan.total_findings ?? 0} /><SummaryCard label="New" value={data.comparison?.new_count ?? data.scan.new_count ?? 0} /><SummaryCard label="Fixed" value={data.comparison?.fixed_count ?? 0} /><SummaryCard label="Persistent" value={data.comparison?.persistent_count ?? 0} /></section><AnalyzerResults runs={data.scan.analyzer_runs} findings={data.findings} selectedAnalyzer={filters.analyzer} onSelect={(analyzer) => updateFilters({ ...filters, analyzer: filters.analyzer === analyzer ? '' : analyzer })} /><section className="findings-section"><div className="section-head"><div><h2>Findings</h2><p>Filter results without leaving the report.</p></div><div className="findings-toolbar"><button className="button secondary" aria-expanded={filtersOpen} aria-controls="finding-filters" onClick={() => setFiltersOpen((open) => !open)}>Filters{activeFilterCount ? ` (${activeFilterCount})` : ''}</button>{activeFilterCount ? <button className="text-button" onClick={clearFilters}>Clear</button> : null}</div></div>{filtersOpen && <FindingFilters filters={filters} setFilters={updateFilters} analyzers={data.scan.analyzer_runs} />}<div className="finding-list">{findings.loading ? <Loading /> : findings.error ? <ErrorPanel error={findings.error} retry={findings.reload} /> : list.length ? <FindingsTable findings={list} onPreview={setPreviewFinding} /> : <Empty title={noFindingsTitle}>{noFindingsCopy}</Empty>}</div>{findings.data && <FindingsPagination total={findings.data.total} offset={findings.data.offset} limit={findings.data.limit} hasMore={findings.data.has_more} onLimit={(next) => { setLimit(next); setOffset(0); }} onPrevious={() => setOffset(Math.max(0, offset - limit))} onNext={() => findings.data?.next_offset !== undefined && setOffset(findings.data.next_offset)} />}</section>{previewFinding && <FindingPreviewDialog scanId={scanId} finding={previewFinding} onClose={() => setPreviewFinding(undefined)} />}</section>;
}
const analyzerDisplayNames: Record<string, string> = { biome: 'Biome', ruff: 'Ruff', semgrep: 'Semgrep', sonarqube: 'SonarQube' };
function analyzerName(id: string) { return analyzerDisplayNames[id] ?? id; }
function AnalyzerResults({ runs, findings, selectedAnalyzer, onSelect }: { runs?: AnalyzerRun[]; findings?: Finding[]; selectedAnalyzer: string; onSelect: (analyzer: string) => void }) {
  if (!runs?.length) return null;
  return <section className="analyzer-results" aria-labelledby="analyzer-results-title"><div className="section-head"><div><h2 id="analyzer-results-title">Analyzer results</h2><p>Every completed check is shown. Select one to filter the combined report.</p></div></div><div className="analyzer-result-list">{runs.map((run) => { const count = findings ? findings.filter((finding) => finding.analyzer_id === run.analyzer_id).length : undefined; const selected = selectedAnalyzer === run.analyzer_id; const status = run.status === 'succeeded' ? 'success' : run.status; return <button type="button" className={`analyzer-result ${selected ? 'selected' : ''}`} aria-pressed={selected} key={run.analyzer_id} onClick={() => onSelect(run.analyzer_id)}><span><strong>{analyzerName(run.analyzer_id)}</strong><small>{run.status === 'succeeded' && count === 0 ? 'Completed with no findings' : run.message || run.status}</small></span><span className={`state ${status}`}>{count === undefined ? 'Results unavailable' : `${count} ${count === 1 ? 'finding' : 'findings'}`}</span></button>; })}</div></section>;
}
function FindingFilters({ filters, setFilters, analyzers }: { filters: FindingFilter; setFilters: (next: FindingFilter) => void; analyzers?: AnalyzerRun[] }) { const set = (key: keyof FindingFilter, value: string) => setFilters({ ...filters, [key]: value }); const tools = [...new Set(analyzers?.map((run) => run.analyzer_id) ?? [])]; return <div className="filters" id="finding-filters"><label>Severity<select value={filters.severity} onChange={(e) => set('severity', e.target.value)}><option value="">All</option>{['critical', 'high', 'medium', 'low', 'info'].map((value) => <option value={value} key={value}>{value}</option>)}</select></label><label>Category<input value={filters.category} onChange={(e) => set('category', e.target.value)} placeholder="All categories" /></label><label>Tool<select value={filters.analyzer} onChange={(e) => set('analyzer', e.target.value)}><option value="">All tools</option>{tools.map((tool) => <option value={tool} key={tool}>{analyzerName(tool)}</option>)}</select></label><label>File<input value={filters.path} onChange={(e) => set('path', e.target.value)} placeholder="Any path" /></label><label>Status<select value={filters.status} onChange={(e) => set('status', e.target.value)}><option value="">All</option><option value="new">New</option><option value="persistent">Persistent</option></select></label><label className="filter-search">Search<input value={filters.q} onChange={(e) => set('q', e.target.value)} placeholder="Message or rule" /></label></div>; }
function FindingsPagination({ total, offset, limit, hasMore, onLimit, onPrevious, onNext }: { total: number; offset: number; limit: number; hasMore: boolean; onLimit: (value: number) => void; onPrevious: () => void; onNext: () => void }) { const first = total ? offset + 1 : 0; const last = Math.min(offset + limit, total); return <nav className="findings-pagination" aria-label="Findings pagination"><span>Showing {first}–{last} of {total}</span><label>Rows<select value={limit} onChange={(event) => onLimit(Number(event.target.value))}><option value={25}>25</option><option value={50}>50</option><option value={100}>100</option></select></label><div><button className="button secondary" onClick={onPrevious} disabled={offset === 0}>Previous</button><button className="button secondary" onClick={onNext} disabled={!hasMore}>Next</button></div></nav>; }
function findingLocation(finding: Finding) { return `${finding.relative_path ?? 'Project-level finding'}${finding.start_line ? `:${finding.start_line}${finding.start_column ? `:${finding.start_column}` : ''}` : ''}`; }
function FindingsTable({ findings, onPreview }: { findings: Finding[]; onPreview: (finding: Finding) => void }) { return <div className="findings-table table-wrap"><table><thead><tr><th>Severity</th><th>Finding</th><th>File</th><th>Tool</th><th>Status</th></tr></thead><tbody>{findings.map((finding) => <tr key={finding.id || finding.fingerprint}><td><span className={`severity ${finding.severity}`}>{finding.severity}</span></td><td className="finding-summary"><strong>{finding.title ?? finding.rule_id ?? 'Finding'}</strong><span className="finding-message">{finding.message}</span>{finding.remediation && <span className="finding-remediation">Fix: {finding.remediation}</span>}{finding.documentation_url && <a href={finding.documentation_url} target="_blank" rel="noreferrer">Rule docs</a>}</td><td>{finding.relative_path && finding.id ? <button type="button" className="finding-file" onClick={() => onPreview(finding)} aria-label={`Preview ${findingLocation(finding)}`}><code>{findingLocation(finding)}</code></button> : <code>{findingLocation(finding)}</code>}</td><td><span className="badge">{finding.analyzer_id}</span>{finding.rule_id && <code>{finding.rule_id}</code>}</td><td>{finding.status ? <span className="status-text">{finding.status}</span> : '—'}</td></tr>)}</tbody></table></div>; }
function FindingPreviewDialog({ scanId, finding, onClose }: { scanId: string; finding: Finding; onClose: () => void }) { const preview = useLoad(() => api.findingPreview(scanId, finding.id), [scanId, finding.id]); const closeRef = useRef<HTMLButtonElement>(null); useEffect(() => { closeRef.current?.focus(); }, []); useEffect(() => { const closeOnEscape = (event: KeyboardEvent) => { if (event.key === 'Escape') onClose(); }; window.addEventListener('keydown', closeOnEscape); return () => window.removeEventListener('keydown', closeOnEscape); }, [onClose]); const data: SourcePreview | undefined = preview.data; return <div className="dialog-backdrop" role="presentation"><dialog open aria-modal="true" aria-labelledby="source-preview-title" className="code-preview-dialog"><div className="confirmation-dialog"><header><div><h2 id="source-preview-title">Source preview</h2><p className="code-preview-location"><code>{findingLocation(finding)}</code></p></div><button ref={closeRef} type="button" className="icon-button" onClick={onClose} aria-label="Close preview">×</button></header>{preview.loading ? <Loading /> : preview.error ? <ErrorPanel error={preview.error} retry={preview.reload} /> : data ? <><p>{data.note ?? 'Current source near this finding.'}</p><pre className="code-preview" aria-label={`Source preview for ${data.path}`}>{data.lines.map((line) => <code key={line.number} className={line.number >= (data.highlight_start_line ?? 0) && line.number <= (data.highlight_end_line ?? 0) ? 'highlight' : ''}><span aria-hidden="true">{line.number}</span>{line.text || ' '}</code>)}</pre></> : null}<footer><button type="button" className="button secondary" onClick={onClose}>Close</button></footer></div></dialog></div>; }

function ToolsPage({ notify }: { notify: (n: Notice) => void }) { const tools = useLoad(api.tools, []); const [busy, setBusy] = useState<string>(); async function action(tool: Tool, operation: 'install' | 'repair' | 'update') { setBusy(`${tool.id}-${operation}`); try { await api.toolAction(tool.id, operation); await tools.reload(); const verb = operation === 'install' ? 'installed' : operation === 'repair' ? 'repaired' : 'updated'; notify({ kind: 'info', text: `${tool.name?.trim() || tool.id}: ${verb}.` }); } catch (e) { notify({ kind: 'error', text: message(e) }); } finally { setBusy(undefined); } } return <div className="page"><header className="page-heading"><div><p className="eyebrow">Managed tools</p><h1>Analysis tools</h1><p>Blunt Code keeps tool setup private and local. Install or repair only when needed.</p></div></header>{tools.loading ? <Loading /> : tools.error ? <ErrorPanel error={tools.error} retry={tools.reload} /> : <div className="tool-table table-wrap"><table><thead><tr><th>Tool</th><th>Version</th><th>Status</th><th>Details</th><th>Actions</th></tr></thead><tbody>{tools.data?.map((tool) => <tr key={tool.id}><td><strong>{tool.name ?? tool.id}</strong></td><td><code>{tool.version ?? 'Managed version'}</code></td><td><span className={`state ${tool.ready ? 'ready' : 'not-ready'}`}>{tool.ready ? 'Ready' : 'Not installed'}</span></td><td>{tool.detail ?? 'Ready for local analysis.'}</td><td className="table-actions"><button className="text-button" disabled={!tool.can_install || busy === `${tool.id}-install`} onClick={() => void action(tool, 'install')}>Install</button><button className="text-button" disabled={!tool.can_install || busy === `${tool.id}-repair`} onClick={() => void action(tool, 'repair')}>Repair</button><button className="text-button" disabled={!tool.can_install || busy === `${tool.id}-update`} onClick={() => void action(tool, 'update')}>Update</button></td></tr>)}</tbody></table></div>}</div>; }
function SettingsPage({ notify }: { notify: (n: Notice) => void }) { const meta = useLoad(api.meta, []); const settings = useLoad(api.settings, []); const [saving, setSaving] = useState(false); const [stopOpen, setStopOpen] = useState(false); const [stopping, setStopping] = useState(false); async function save(input: { offline?: boolean; open_browser?: boolean }) { setSaving(true); try { await api.saveSettings(input); await settings.reload(); } catch (e) { notify({ kind: 'error', text: message(e) }); } finally { setSaving(false); } } async function stop() { setStopping(true); try { await api.stopServer(); setStopOpen(false); notify({ kind: 'info', text: 'Blunt Code is stopping. You can close this tab.' }); } catch (e) { notify({ kind: 'error', text: message(e) }); setStopping(false); } } return <div className="page"><header className="page-heading"><div><p className="eyebrow">Settings</p><h1>Application settings</h1><p>Blunt Code keeps configuration small and local.</p></div></header><div className="settings-list"><section><h2>General</h2><div className="setting"><div><h3>Open browser automatically</h3><p>Open the local interface when Blunt Code starts.</p></div><button className="button secondary" disabled={settings.loading || saving} onClick={() => void save({ open_browser: !(settings.data?.open_browser ?? true) })}>{settings.data?.open_browser ?? true ? 'Browser opens on launch' : 'Browser stays closed'}</button></div><div className="setting"><div><h3>Offline mode</h3><p>Do not download tools or check for updates. Installed tools can still scan local workspaces.</p></div><button className="button secondary" disabled={settings.loading || saving} onClick={() => void save({ offline: !(settings.data?.offline ?? false) })}>{settings.data?.offline ? 'Offline mode on' : 'Offline mode off'}</button></div></section><section><h2>Analysis</h2><Setting label="Default scan profile" description="Workspace scans use the saved profile unless you choose another profile." value="Workspace managed" /><Setting label="Include style findings" description="Style and formatting findings can be configured with workspace rules." value="Workspace managed" /></section><section><h2>Privacy</h2><Setting label="Telemetry" description="Blunt Code does not send usage analytics or repository data to a cloud service." value="Disabled" /><Setting label="Data directory" description="Application state, tool installs, and scan history are kept on this computer." value={meta.data?.data_directory ?? (meta.loading ? 'Loading…' : 'Available from local metadata')} /></section><section><h2>Server</h2><div className="setting danger-setting"><div><h3>Stop local server</h3><p>End this Blunt Code session. Any active scan will be cancelled; your saved workspaces and reports stay on this computer.</p></div><button className="button danger" onClick={() => setStopOpen(true)}>Stop server</button></div></section></div>{stopOpen && <ConfirmationDialog title="Stop Blunt Code?" description="The local server will stop and this page will disconnect. You can start Blunt Code again whenever you need it." confirmLabel="Stop server" busy={stopping} onCancel={() => setStopOpen(false)} onConfirm={stop} />}</div>; }
function Setting({ label, description, value }: { label: string; description: string; value: string }) { return <div className="setting"><div><h3>{label}</h3><p>{description}</p></div><span>{value}</span></div>; }
function AboutPage() { const meta = useLoad(api.meta, []); const health = useLoad(api.health, []); return <div className="page narrow"><header className="page-heading"><div><p className="eyebrow">About</p><h1>Blunt Code</h1><p>A local-first static analysis application for Windows.</p></div></header><section className="about-card"><h2>Local by default</h2><p>Blunt Code analyzes selected files on this computer and combines results from local analysis tools. It does not require an account, telemetry, or an AI provider.</p><dl><dt>Server</dt><dd>{health.loading ? 'Checking…' : health.error ? 'Unavailable' : health.data?.status ?? 'Ready'}</dd><dt>Version</dt><dd>{meta.data?.version ?? 'Unknown'}</dd><dt>API version</dt><dd>{meta.data?.api_version ?? 'Unknown'}</dd><dt>Platform</dt><dd>{[meta.data?.os, meta.data?.architecture].filter(Boolean).join(' / ') || 'Unknown'}</dd></dl></section></div>; }

function AddWorkspaceDialog({ onClose, onCreated, notify }: { onClose: () => void; onCreated: (workspace: Workspace) => void; notify: (n: Notice) => void }) { const [path, setPath] = useState(''); const [name, setName] = useState(''); const [busy, setBusy] = useState(false); const pick = async () => { setBusy(true); try { const result = await api.selectFolder(); if (!result.cancelled && result.path) { setPath(result.path); setName((current) => current || result.path!.split(/[\\/]/).filter(Boolean).pop() || 'Workspace'); } } catch (e) { notify({ kind: 'error', text: message(e) }); } finally { setBusy(false); } }; const submit = async (event: FormEvent) => { event.preventDefault(); if (!path.trim()) return; setBusy(true); try { onCreated(await api.createWorkspace({ root_path: path.trim(), name: name.trim() || undefined })); } catch (e) { notify({ kind: 'error', text: message(e) }); } finally { setBusy(false); } }; return <div className="dialog-backdrop" role="presentation"><dialog open aria-labelledby="add-workspace-title"><form onSubmit={(event) => void submit(event)}><header><h2 id="add-workspace-title">Add workspace</h2><button type="button" className="icon-button" onClick={onClose} aria-label="Close">×</button></header><p>Choose a project folder. Blunt Code keeps a reference and never changes your source files.</p><label>Folder path<div className="picker-row"><input autoFocus value={path} onChange={(event) => setPath(event.target.value)} placeholder="C:\\Projects\\my-app" required /><button type="button" className="button secondary" onClick={() => void pick()} disabled={busy}>Browse…</button></div></label><label>Workspace name <input value={name} onChange={(event) => setName(event.target.value)} placeholder="Optional" /></label><footer><button type="button" className="button secondary" onClick={onClose}>Cancel</button><button className="button primary" disabled={busy || !path.trim()}>{busy ? 'Adding…' : 'Add workspace'}</button></footer></form></dialog></div>; }
function ConfirmationDialog({ title, description, confirmLabel, busy, onCancel, onConfirm }: { title: string; description: string; confirmLabel: string; busy: boolean; onCancel: () => void; onConfirm: () => void }) { const cancelRef = useRef<HTMLButtonElement>(null); useEffect(() => { cancelRef.current?.focus(); }, []); useEffect(() => { const closeOnEscape = (event: KeyboardEvent) => { if (event.key === 'Escape' && !busy) onCancel(); }; window.addEventListener('keydown', closeOnEscape); return () => window.removeEventListener('keydown', closeOnEscape); }, [busy, onCancel]); return <div className="dialog-backdrop" role="presentation"><dialog open aria-modal="true" aria-labelledby="confirmation-title"><div className="confirmation-dialog"><header><h2 id="confirmation-title">{title}</h2><button type="button" className="icon-button" onClick={onCancel} disabled={busy} aria-label="Close">×</button></header><p>{description}</p><footer><button ref={cancelRef} type="button" className="button secondary" onClick={onCancel} disabled={busy}>Cancel</button><button type="button" className="button danger" onClick={onConfirm} disabled={busy}>{busy ? 'Working…' : confirmLabel}</button></footer></div></dialog></div>; }
